      if bit_to_bool(target[1]) & not(extensionEnabled(Ext_C)) 
      then { 
        handle_mem_exception(target, E_Fetch_Addr_Align()); 
        RETIRE_FAIL 
      } else { 
        X(rd) = get_next_pc(); 
        set_next_pc(target); 
        RETIRE_SUCCESS 
      } 
    }else { 
      RETIRE_FAIL 
    }; 
  } 
}

